search.filter:
correlate(
  pr2_event: { 
    #repo="base_sensor" #event_simpleName="ProcessRollup2" 
    | event_platform="Lin"
    | ParentBaseFileName=/ssm/ OR FileName=/ssm/
    } include: [ParentBaseFileName, FileName, CommandLine,UserName,ComputerName],
  atr_event: { 
    #repo="base_sensor" #event_simpleName="AssociateTreeIdWithRoot" 
    | event_platform="Lin" 
    | SessionProcessId <=> pr2_event.SessionProcessId 
    | aid <=> pr2_event.aid  
    } include: [DetectDescription,Tactic,Technique,DetectName],
  aws_ssm_event: { 
    #Vendor="aws" #event.module="cloudtrail" #repo!="xdr*" #event.outcome="success"
    | event.provider="ssm.amazonaws.com"
    | case {
        event.action="StartSession" | cloud.instance.id := Vendor.requestParameters.target | Command := Vendor.requestParameters.parameters.command[0];
        event.action="SendCommand" | cloud.instance.id:= Vendor.requestParameters.instanceIds[0] | DocumentName:= Vendor.requestParameters.documentName | Parameters:=Vendor.requestParameters.parameters
    }
    | identity.arn := Vendor.userIdentity.arn
    | match(file="aid_master_details.csv", field=cloud.instance.id, include=[aid],strict=true) 
    | aid <=> atr_event.aid 
    } include: [event.action, Vendor.userIdentity.arn, cloud.instance.id, Command, user.name,cloud.account.id,identity.arn, DocumentName, Parameters],
    sequence=false,
    within=10m
)
